function makeReaders() {
  return {
    arrow: () => this.id,
    regular() {
      return this.id;
    },
  };
}

const a = { id: "a" };
const b = { id: "b" };

const readers = makeReaders.call(a);
readers.id = "readers";

console.log(readers.arrow());
console.log(readers.regular());
console.log(readers.arrow.call(b));
console.log(readers.regular.bind(b)());
console.log(makeReaders.bind(b)().arrow.call(a));
